import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]


def play(l, r):
    # best (mover score - other score) obtainable from a[l..r]
    if l > r:
        return 0
    return max(a[l] - play(l + 1, r), a[r] - play(l, r - 1))


print('true' if play(0, n - 1) >= 0 else 'false')

